dd.artwork:
action_ref = SHA-256(canonicalize({
  agentId,
  actionType,
  scopeRequired,
  timestamp
}))

section.artwork:
import { generateIssuerKey } from '@scopeblind/passport';
const issuer = generateIssuerKey();
console.log(issuer.issuerId);
console.log(issuer.publicKeyHex);
// One run printed:
// sb:issuer:BrmdDbomqHgK
// a154c931eb9b746c8d3b07dcca39bc3680ecc0dc5cc2d5e385522954a1f0ab0c

import { signReceipt } from '@scopeblind/passport';
import { writeFileSync } from 'node:fs';

const receipt = signReceipt(
  {
    type: "protectmcp:decision",
    tool_name: "deploy",
    decision: "allow",
    agent_tier: "privileged",
    policy_digest: "sha256:" +
      "ba145cbc4d96bea7c7590e4f24295925" +
      "6b59b0075163bab6f53f4b300957c7ba",
    issued_at: "2026-03-22T14:32:06.551Z",
    issuer_id: issuer.issuerId
  },
  issuer.secretKeyHex,
  issuer.issuerId
);
writeFileSync('receipt.json', JSON.stringify(receipt, null, 2));
